mapper.select:
SELECT w.id, w.title, w.content, w.work_type, w.status, w.priority, w.reporter_id, w.assignee_id, w.organization_id, w.due_date, w.order_num, w.is_archived, w.created_at, w.updated_at, u1.username AS reporter_name, u2.username AS assignee_name FROM works w LEFT JOIN users u1 ON w.reporter_id = u1.id LEFT JOIN users u2 ON w.assignee_id = u2.id
AND w.work_type = #{workType}
AND w.status = #{status}
AND w.priority = #{priority}
AND w.assignee_id = #{assigneeId}
AND (w.title ILIKE '%' || #{keyword} || '%' OR w.content ILIKE '%' || #{keyword} || '%')
AND w.is_archived = #{isArchived}
AND w.is_archived = false
ORDER BY
CASE w.priority WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 END, w.created_at DESC, w.id DESC
w.status, w.created_at DESC, w.id DESC
w.due_date ASC NULLS LAST, w.created_at DESC, w.id DESC
w.order_num ASC NULLS LAST, w.created_at DESC, w.id DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
UPDATE works
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE works
SET assignee_id = #{assigneeId}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE works
SET priority = #{priority}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

